sysauto_script.script:
// Query the entire list of PDIs from the PDIObserver application table
var grPDI = new GlideRecord('x_1836491_pdiobs_0_observer_instance');
grPDI.query();

while (grPDI.next()) {
    var targetURL = grPDI.getValue('instance_url');
    var username = grPDI.getValue('instance_username');

    // Decrypt the 2-way encrypted password into plaintext to pass into the API
    var password = grPDI.instance_password.getDecryptedValue();

    if (!targetURL || !username || !password) {
        continue; // Skip if configuration is missing information
    }

    var endpoint = targetURL + '/api/now/table/sys_properties?sysparm_query=name=glide.war&sysparm_fields=value&sysparm_limit=1';

    try {
        var request = new sn_ws.RESTMessageV2();
        request.setEndpoint(endpoint);
        request.setHttpMethod('GET');
        request.setRequestHeader('Accept', 'application/json');
        request.setBasicAuth(username, password);

        // Set timeout (5 seconds) so the Scheduled Job doesn't hang if the PDI is hibernating
        request.setHttpTimeout(5000);

        var response = request.execute();
        var statusCode = response.getStatusCode();
        var responseBody = response.getBody();
        var currentTime = new GlideDateTime().getDisplayValue();


        var currentLog1 = grPDI.getValue('log1') || '';
        var currentLog2 = grPDI.getValue('log2') || '';
        grPDI.setValue('log3', currentLog2);
        grPDI.setValue('log2', currentLog1);

        if (statusCode === 200) {
            var parsed = JSON.parse(responseBody);
            if (parsed.result && parsed.result.length > 0) {
                var buildWar = parsed.result[0].value;

                // Extract and format the version string 
                var versionMatch = buildWar.match(/glide-([a-z]+)-.*__patch(\d+)-/);
                var formattedVersion = buildWar; // Default to raw string
                if (versionMatch && versionMatch.length === 3) {
                    var releaseName = versionMatch[1].charAt(0).toUpperCase() + versionMatch[1].slice(1);
                    formattedVersion = releaseName + " Patch " + versionMatch[2];
                }
                // Update version and log successful API call
                grPDI.setValue('version', formattedVersion);
                var logMsg = '[' + currentTime + '] 200 OK - ALIVE. Version: ' + buildWar;
                grPDI.setValue('log1', logMsg);
            }
        } else {
            // Log error (wrong password, missing privileges, etc.), shifting previous logs 
            var errorLogMsg = '[' + currentTime + '] Error ' + statusCode + ': ' + responseBody;
            grPDI.setValue('log1', errorLogMsg);
        }

    } catch (ex) {
        var errorMsg = ex.getMessage ? ex.getMessage() : ex;
        // Log Timeout or PDI hibernating/unreachable error, shifting previous logs 
        var excLogMsg = '[' + currentTime + '] EXCEPTION (Hibernating or Unreachable): ' + errorMsg;
        var excLog1 = grPDI.getValue('log1') || '';
        var excLog2 = grPDI.getValue('log2') || '';

        grPDI.setValue('log3', excLog2);
        grPDI.setValue('log2', excLog1);
        grPDI.setValue('log1', excLogMsg);
    }

    // Update the last check time and save the record
    grPDI.setValue('last_check_time', new GlideDateTime());
    grPDI.update();
}
